insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T01-L01-E06','pronunciation_recording','pronunciation','Escucha y graba: ''B, V. Could you repeat that, please?''','B, V. Could you repeat that, please?','Se entiende la aclaración. Practica ahora dentro del diálogo.','[]'::jsonb,'{"id":"A1-M1-T01-L01-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Escucha y graba: ''B, V. Could you repeat that, please?''","prompt":"B, V. Could you repeat that, please?","evaluation":{"0":"intelligibility","1":"B-V contrast","2":"polite intonation","open_response":true,"status":"pending_rubric"},"estimated_seconds":90,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M1-T01-L01","pronunciation":{"target":"Distinguir los nombres de B y V y producir la frase ''How do you spell it?'' con ritmo comprensible.","models":[{"text":"B","ipa":"/biː/","contrast":"bee"},{"text":"V","ipa":"/viː/","contrast":"vee"},{"text":"How do you spell it?","stress":["How","spell"]}],"student_feedback":"Evalúa inteligibilidad, diferencia B/V y ritmo de la pregunta. No penalices el acento extranjero si el mensaje se entiende."}}'::jsonb,'Se entiende la aclaración. Practica ahora dentro del diálogo.','En V, toca el labio inferior con los dientes superiores y deja salir aire.',90,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
