insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T01-L02-E07','interactive_reading','reading','Lee la historia y toca ''receptionist'', ''sure'' y ''repeat'' para ver ejemplos.','Lee la historia y toca ''receptionist'', ''sure'' y ''repeat'' para ver ejemplos.','Encontraste el problema y la forma de resolverlo.','[["At a hotel","He is at a hotel","A hotel"],["The receptionist is not sure","Because the receptionist is not sure","To clarify the letter"]]'::jsonb,'{"id":"A1-M1-T01-L02-E07","type":"interactive_reading","skill":"reading","instruction":"Lee la historia y toca ''receptionist'', ''sure'' y ''repeat'' para ver ejemplos.","reading_ref":"A1-M1-T01-L02-reading-01","estimated_seconds":120,"prompt":"Lee la historia y toca ''receptionist'', ''sure'' y ''repeat'' para ver ejemplos.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T01-L02","reading":{"title":"The registration form","text":"Luis is checking in at a hotel. The receptionist writes his email address. Luis says, ''luis.vera@example.com.'' The receptionist is not sure about the first letter of Vera. Luis repeats it and gives an example: ''V as in very.'' The receptionist checks the address again.","interactive_vocabulary":["checking in","receptionist","sure","repeats","example"],"questions":[{"prompt":"Where is Luis?","options":["At a hotel","At a school","At a restaurant"]},{"prompt":"Why does Luis repeat the letter?","options":["The receptionist is not sure","He wants a drink","He is leaving"]}]},"vocabulary":[{"term":"first letter","meaning_es":"primera letra","example":"What''s the first letter?"},{"term":"last letter","meaning_es":"última letra","example":"I didn''t catch the last letter."},{"term":"again","meaning_es":"otra vez","example":"Could you say that again?"},{"term":"catch","meaning_es":"entender / captar","example":"I didn''t catch that."},{"term":"address","meaning_es":"dirección","example":"What''s your email address?"},{"term":"missing","meaning_es":"que falta","example":"Find the missing letter."}]}'::jsonb,'Encontraste el problema y la forma de resolverlo.','Busca qué palabra no entiende la recepcionista y qué hace Luis después.',120,1,7,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
