insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T01-L03-E06','pronunciation_recording','pronunciation','Graba la confirmación completa con la entonación adecuada.','G-A-R-C-I-A. Is that right? Yes, that''s right.','La secuencia se entiende y la pregunta se diferencia de la confirmación.','[]'::jsonb,'{"id":"A1-M1-T01-L03-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Graba la confirmación completa con la entonación adecuada.","prompt":"G-A-R-C-I-A. Is that right? Yes, that''s right.","evaluation":{"0":"letter clarity","1":"question intonation","2":"confirmation rhythm","open_response":true,"status":"pending_rubric"},"estimated_seconds":100,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M1-T01-L03","pronunciation":{"target":"Deletrear grupos de letras con ritmo constante y confirmar información con entonación natural.","models":[{"text":"E-L-E-N-A","note":"separa las letras con pausas breves"},{"text":"Is that right?","stress":["right"],"intonation":"rising"},{"text":"Yes, that''s right.","stress":["right"],"intonation":"falling"}],"student_feedback":"Evalúa claridad de cada letra, pausas breves y diferencia entre pregunta y confirmación."}}'::jsonb,'La secuencia se entiende y la pregunta se diferencia de la confirmación.','Sube ligeramente la entonación en Is that right? y bájala en Yes, that''s right.',100,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,est