insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T01-L03-E07','interactive_reading','reading','Lee el texto, consulta las palabras nuevas y completa la ficha de Elena.','Lee el texto, consulta las palabras nuevas y completa la ficha de Elena.','Usaste la lectura para recuperar información específica.','[["A train ticket","She is buying a train ticket","Train ticket"],["Reads it back","The agent reads it back","Reads the information back"]]'::jsonb,'{"id":"A1-M1-T01-L03-E07","type":"interactive_reading","skill":"reading","instruction":"Lee el texto, consulta las palabras nuevas y completa la ficha de Elena.","reading_ref":"A1-M1-T01-L03-reading-01","estimated_seconds":130,"prompt":"Lee el texto, consulta las palabras nuevas y completa la ficha de Elena.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T01-L03","reading":{"title":"A travel form","text":"Elena is buying a train ticket. The agent asks for her first name, last name, city and email address. Elena spells each piece of information. The agent reads the information back to her. Elena listens and confirms that everything is right.","interactive_vocabulary":["buying","train ticket","piece of information","reads back","everything"],"questions":[{"prompt":"What is Elena buying?","options":["A train ticket","A hotel room","A coffee"]},{"prompt":"What does the agent do after writing the information?","options":["Reads it back","Deletes it","Changes the city"]}]},"vocabulary":[{"term":"first name","meaning_es":"nombre de pila","example":"My first name is Ana."},{"term":"last name","meaning_es":"apellido","example":"My last name is García."},{"term":"city","meaning_es":"ciudad","example":"I live in a small city."},{"term":"country","meaning_es":"país","example":"What country are you from?"},{"term":"form","meaning_es":"formulario","example":"Please complete this form."},{"term":"right","meaning_es":"correcto","example":"Yes, that''s right."},{"term":"again","meaning_es":"otra vez","example":"Let me spell it again."}]}'::jsonb,'Usaste la lectura para recuperar información específica.','Busca qué compra Elena y qué información lee el agente.',130,1,7,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
