xercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T01-L04-E07','interactive_reading','reading','Lee la historia y reconstruye los tres pasos que usó Victor.','Lee la historia y reconstruye los tres pasos que usó Victor.','Identificaste una estrategia de comunicación útil.','[["The lobby is noisy","Noise","The noise","It is noisy"],["M as in Monday","He says M as in Monday","With M as in Monday"]]'::jsonb,'{"id":"A1-M1-T01-L04-E07","type":"interactive_reading","skill":"reading","instruction":"Lee la historia y reconstruye los tres pasos que usó Victor.","reading_ref":"A1-M1-T01-L04-reading-01","steps":["repeat the letter","give an example","spell the name again"],"estimated_seconds":130,"prompt":"Lee la historia y reconstruye los tres pasos que usó Victor.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T01-L04","reading":{"title":"A noisy hotel lobby","text":"Victor arrives at a hotel with a reservation. The lobby is busy and noisy. The receptionist cannot hear the first letter of his last name. Victor does not simply repeat the whole name quickly. He gives an example: ''M as in Monday.'' The receptionist writes the name correctly and confirms the reservation.","interactive_vocabulary":["arrives","busy","noisy","cannot hear","gives an example","confirms"],"questions":[{"prompt":"What makes the interaction difficult?","options":["The lobby is noisy","Victor has no reservation","The hotel is closed"]},{"prompt":"How does Victor clarify M?","options":["M as in Monday","M as in music","He changes his name"]}]},"vocabulary":[{"term":"reservation","meaning_es":"reserva","example":"I have a reservation."},{"term":"confirmation","meaning_es":"confirmación","example":"Here is your confirmation."},{"term":"noise","meaning_es":"ruido","example":"There is a lot of noise."},{"term":"correct","meaning_es":"correcto","example":"Is this correct?"},{"term":"wrong","meaning_es":"equivocado","example":"That letter is wrong."},{"term":"clarify","meaning_es":"aclarar","example":"I need to clarify one letter."}]}'::jsonb,'Identificaste una estrategia de comunicación útil.','Victor primero aclara la letra, luego da un ejemplo y finalmente repite el nombre.',130,1,7,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
