insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T02-L04-E05','interactive_reading','reading','Lee el texto y señala a qué se refiere cada pronombre.','Lee el texto y señala a qué se refiere cada pronombre.','Seguiste las referencias de personas, grupos y objetos.','[["Omar"],["Maya''s name"]]'::jsonb,'{"id":"A1-M1-T02-L04-E05","type":"interactive_reading","skill":"reading","instruction":"Lee el texto y señala a qué se refiere cada pronombre.","reading_ref":"A1-M1-T02-L04-reading-01","estimated_seconds":135,"prompt":"Lee el texto y señala a qué se refiere cada pronombre.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T02-L04","reading":{"title":"The community event","text":"Leo welcomes Maya at a community event. He introduces Omar, the organizer, and Nina, a participant. Maya asks about another group. They are the blue team. Leo gives Maya a badge. It has her name. Everyone is ready to begin.","interactive_vocabulary":["welcomes","community","organizer","another","ready","begin"],"questions":[{"prompt":"Who is the organizer?","options":["Omar","Leo","Maya"]},{"prompt":"What does the badge have?","options":["Maya''s name","The blue team","A phone"]}]},"vocabulary":[{"term":"participant","meaning_es":"participante","example":"She is a participant."},{"term":"organizer","meaning_es":"organizador / organizadora","example":"He is the organizer."},{"term":"team","meaning_es":"equipo","example":"We are the blue team."},{"term":"badge","meaning_es":"credencial","example":"It is your badge."},{"term":"event","meaning_es":"evento","example":"We are at an event."},{"term":"everyone","meaning_es":"todos","example":"Everyone is here."}]}'::jsonb,'Seguiste las referencias de personas, grupos y objetos.','Vuelve al texto y localiza quién organiza, qué grupo participa y qué tiene el badge.',135,1,5,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T02-L04-E06','pronunciation_recording','pronunciation','Graba una presentación con todos los pronombres que puedas usar naturalmente.','I am ____. You are ____. He is ____. She is ____. It is ____. We are ____. They are ____.','Los pronombres se entienden dentro de frases completas.','[]'::jsonb,'{"id":"A1-M1-T02-L04-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Graba una presentación con todos los pronombres que puedas usar naturalmente.","prompt":"I am ____. You are ____. He is ____. She is ____. It is ____. We are ____. They are ____.","evaluation":{"0":"pronoun intelligibility","1":"referent clarity","2":"sentence rhythm","open_response":true,"status":"pending_rubric"},"estimated_seconds":120,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M1-T02-L04","pronunciation":{"target":"Producir los pronombres dentro de frases con ritmo comprensible y distinguir he, she, we, they e it.","models":[{"text":"I am here.","ipa":"/aɪ æm hɪr/"},{"text":"You are here.","ipa":"/juː ɑːr hɪr/"},{"text":"He is the organizer.","stress":["He","organizer"]},{"text":"She is a participant.","stress":["She","participant"]},{"text":"We are all here.","stress":["We","here"]},{"text":"They are the blue team.","stress":["They","blue team"]},{"text":"It is your badge.","stress":["It","badge"]}],"student_feedback":"La meta es que el interlocutor identifique el referente; no se penaliza un acento extranjero comprensible."}}'::jsonb,'Los pronombres se entienden dentro de frases completas.','No intentes decirlos demasiado rápido; usa pausas breves y frases claras.',120,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
