insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T07-L03-E06','pronunciation_recording','pronunciation','Graba una comparación entre los dos equipos.','Our room is small. Their room is large.','Se entiende qué grupo posee cada sala.','[]'::jsonb,'{"id":"A1-M1-T07-L03-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Graba una comparación entre los dos equipos.","prompt":"Our room is small. Their room is large.","evaluation":{"0":"our/their contrast","1":"group reference","2":"adjective clarity","open_response":true,"status":"pending_rubric"},"estimated_seconds":90,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M1-T07-L03","pronunciation":{"target":"Distinguir our y their, especialmente their frente a they''re.","models":[{"text":"our","ipa":"/aʊər/"},{"text":"their","ipa":"/ðer/"},{"text":"Our team is ready.","stress":["our","team","ready"]},{"text":"Their bags are here.","stress":["their","bags","here"]}],"student_feedback":"Enfatiza our o their cuando necesitas aclarar qué grupo es el dueño."}}'::jsonb,'Se entiende qué grupo posee cada sala.','Enfatiza our y their para marcar la diferencia entre equipos.',90,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
