ack_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T07-L04-E07','interactive_reading','reading','Lee la escena y completa un registro de dueño y objeto.','Lee la escena y completa un registro de dueño y objeto.','Relacionaste varios posesivos con sus dueños.','[["Daniel''s"],["In another box"]]'::jsonb,'{"id":"A1-M1-T07-L04-E07","type":"interactive_reading","skill":"reading","instruction":"Lee la escena y completa un registro de dueño y objeto.","reading_ref":"A1-M1-T07-L04-reading-01","estimated_seconds":135,"prompt":"Lee la escena y completa un registro de dueño y objeto.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T07-L04","reading":{"title":"Sorting the lost things","text":"After the event, Maya and Leo work at the lost-and-found desk. They find Daniel''s black backpack and Sofia''s blue scarf. They put their belongings in separate boxes. The volunteers keep their own equipment in another box.","interactive_vocabulary":["sorting","lost-and-found desk","separate","belongings","own equipment"],"questions":[{"prompt":"Whose backpack do they find?","options":["Daniel''s","Sofia''s","The volunteers''"]},{"prompt":"Where do the volunteers keep their equipment?","options":["In another box","In Daniel''s backpack","On the desk"]}]},"vocabulary":[{"term":"lost and found","meaning_es":"objetos perdidos","example":"The lost-and-found desk is here."},{"term":"owner","meaning_es":"dueño / dueña","example":"Find the owner."},{"term":"scarf","meaning_es":"bufanda","example":"Her scarf is blue."},{"term":"backpack","meaning_es":"mochila","example":"His backpack is black."},{"term":"equipment","meaning_es":"equipo / material","example":"Our equipment is ready."},{"term":"whose","meaning_es":"de quién","example":"Whose bag is this?"}]}'::jsonb,'Relacionaste varios posesivos con sus dueños.','Daniel tiene el backpack; Sofia tiene la scarf; los voluntarios tienen equipment.',135,1,7,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
