insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T08-L04-E05','interactive_reading','reading','Lee las indicaciones y crea un mapa de cuatro referencias.','Lee las indicaciones y crea un mapa de cuatro referencias.','Comprendiste indicaciones con singular, plural, cerca y lejos.','[["Room 2"],["Near the window"]]'::jsonb,'{"id":"A1-M1-T08-L04-E05","type":"interactive_reading","skill":"reading","instruction":"Lee las indicaciones y crea un mapa de cuatro referencias.","reading_ref":"A1-M1-T08-L04-reading-01","estimated_seconds":135,"prompt":"Lee las indicaciones y crea un mapa de cuatro referencias.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T08-L04","reading":{"title":"A guide to the center","text":"This is the entrance desk. That is the sign for Room 2. These are the materials for the workshop. Those are the shelves near the window. The visitor thanks the guide because the directions are clear.","interactive_vocabulary":["entrance desk","directions","clear","workshop","shelves"],"questions":[{"prompt":"What is the sign for?","options":["Room 2","The window","The desk"]},{"prompt":"Where are the shelves?","options":["Near the window","At the entrance desk","Outside"]}]},"vocabulary":[{"term":"visitor","meaning_es":"visitante","example":"The visitor is here."},{"term":"entrance","meaning_es":"entrada","example":"That is the entrance."},{"term":"sign","meaning_es":"letrero / señal","example":"This is a sign."},{"term":"materials","meaning_es":"materiales","example":"These are the materials."},{"term":"shelves","meaning_es":"estantes","example":"Those are the shelves."},{"term":"nearby","meaning_es":"cercano","example":"The chairs are nearby."}]}'::jsonb,'Comprendiste indicaciones con singular, plural, cerca y lejos.','Relaciona this/that/these/those con desk, entrance, materials y shelves.',135,1,5,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
