insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T09-L04-E02','listening_report_sequence','listening','Escucha el reporte y ordena los tres pasos.','There is a projector. There aren''t any markers. We need markers.','Entendiste la lógica de un reporte útil.','["describe what exists, report what is missing, propose a need"]'::jsonb,'{"id":"A1-M1-T09-L04-E02","type":"listening_report_sequence","skill":"listening","instruction":"Escucha el reporte y ordena los tres pasos.","prompt":"There is a projector. There aren''t any markers. We need markers.","steps":["describe what exists","report what is missing","propose a need"],"estimated_seconds":70,"difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T09-L04","listening":{"dialogue":[{"speaker":"Manager","text":"Is the room ready?"},{"speaker":"Assistant","text":"Almost. There is a projector and there are twelve seats."},{"speaker":"Manager","text":"Are there any markers?"},{"speaker":"Assistant","text":"No, there aren''t any markers. There is an extension cord, though."},{"speaker":"Manager","text":"Okay. We need markers. Are there enough seats?"},{"speaker":"Assistant","text":"Yes, there are. The room is ready after we get the markers."}],"audio_text":null}}'::jsonb,'Entendiste la lógica de un reporte útil.','Primero se describe, luego se reporta el problema y finalmente se propone una acción.',70,1,2,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T09-L04-E03','mixed_grammar_choice','grammar','Completa cada parte de la revisión.','Completa cada parte de la revisión.','Elegiste forma según cantidad y afirmación/negación.','["is","are","aren''t"]'::jsonb,'{"id":"A1-M1-T09-L04-E03","type":"mixed_grammar_choice","skill":"grammar","instruction":"Completa cada parte de la revisión.","items":[{"prompt":"There ___ a projector.","options":["is","are"],"answer":"is"},{"prompt":"There ___ twelve seats.","options":["are","is"],"answer":"are"},{"prompt":"There ___ any markers.","options":["aren''t","isn''t"],"answer":"aren''t"}],"estimated_seconds":75,"prompt":"Completa cada parte de la revisión.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T09-L04"}'::jsonb,'Elegiste forma según cantidad y afirmación/negación.','Projector es singular; seats y markers son plurales.',75,1,3,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
