insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T09-L04-E05','error_correction','grammar','Corrige el reporte completo.','There is twelve seats. There aren''t a projector.','Corregiste número y forma singular/plural.','["There are twelve seats. There isn''t a projector."]'::jsonb,'{"id":"A1-M1-T09-L04-E05","type":"error_correction","skill":"grammar","instruction":"Corrige el reporte completo.","prompt":"There is twelve seats. There aren''t a projector.","estimated_seconds":65,"difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T09-L04"}'::jsonb,'Corregiste número y forma singular/plural.','Twelve seats = there are; a projector = there isn''t.',65,1,5,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T09-L04-E06','pronunciation_recording','pronunciation','Graba el reporte completo de la sala.','There is a projector. There are twelve seats. There aren''t any markers. We need markers.','El reporte tiene información y una solución clara.','[]'::jsonb,'{"id":"A1-M1-T09-L04-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Graba el reporte completo de la sala.","prompt":"There is a projector. There are twelve seats. There aren''t any markers. We need markers.","evaluation":{"0":"is/are contrast","1":"negative clarity","2":"solution clarity","open_response":true,"status":"pending_rubric"},"estimated_seconds":130,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M1-T09-L04","pronunciation":{"target":"Mantener claridad en un reporte con afirmaciones, preguntas y problemas.","models":[{"text":"There is a projector.","stress":["projector"]},{"text":"Are there any markers?","stress":["markers"],"intonation":"rising"},{"text":"There aren''t any markers.","stress":["aren''t","markers"]},{"text":"We need markers.","stress":["need","markers"]}],"student_feedback":"Organiza el reporte en bloques: qué hay, qué falta y qué acción se necesita."}}'::jsonb,'El reporte tiene información y una solución clara.','Haz pausas entre los tres bloques: existe, falta, necesitamos.',130,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M1-T09-L04-E07','interactive_reading','reading','Lee la revisión y completa la lista final de preparación.','Lee la revisión y completa la lista final de preparación.','Convertiste el texto en una lista de acciones.','[["A projector and twelve seats"],["Markers and an extension cord"]]'::jsonb,'{"id":"A1-M1-T09-L04-E07","type":"interactive_reading","skill":"reading","instruction":"Lee la revisión y completa la lista final de preparación.","reading_ref":"A1-M1-T09-L04-reading-01","estimated_seconds":135,"prompt":"Lee la revisión y completa la lista final de preparación.","difficulty":null,"target_error":null,"evaluation":{"open_response":false,"status":"auto_check_candidate"},"hint":null,"source_lesson_id":"A1-M1-T09-L04","reading":{"title":"Fifteen minutes before the meeting","text":"Fifteen minutes before the meeting, the team checks the room. There is a projector and there are twelve seats. There are no markers, and there isn''t an extension cord. The team needs markers and an extension cord. After that, the room is ready.","interactive_vocabulary":["fifteen minutes","checks","extension cord","after that","meeting"],"questions":[{"prompt":"What is in the room?","options":["A projector and twelve seats","Markers and an extension cord","Only tables"]},{"prompt":"What does the team need?","options":["Markers and an extension cord","More seats","A new room"]}]},"vocabulary":[{"term":"readiness check","meaning_es":"revisión de preparación","example":"Let''s do a readiness check."},{"term":"projector","meaning_es":"proyector","example":"There is a projector."},{"term":"extension cord","meaning_es":"cable de extensión","example":"There isn''t an extension cord."},{"term":"seats","meaning_es":"asientos","example":"There are enough seats."},{"term":"markers","meaning_es":"marcadores","example":"There aren''t any markers."},{"term":"ready","meaning_es":"listo / lista","example":"The room is ready."}]}'::jsonb,'Convertiste el texto en una lista de acciones.','Busca projector, seats, markers, extension cord y la solución.',135,1,7,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
