insert into public.exercises(lesson_id,content_code,exercise_type,skill,instruction,prompt,explanation,correct_answer,content_payload,feedback_correct,feedback_incorrect,estimated_seconds,difficulty,sort_order,is_published) values(v_lesson_id,'A1-M2-T03-L02-E06','pronunciation_recording','pronunciation','Graba tres preguntas y respuestas cortas.','Do you work here? Yes, I do. Does she drive? No, she doesn''t.','Las respuestas son breves pero completas.','[]'::jsonb,'{"id":"A1-M2-T03-L02-E06","type":"pronunciation_recording","skill":"pronunciation","instruction":"Graba tres preguntas y respuestas cortas.","prompt":"Do you work here? Yes, I do. Does she drive? No, she doesn''t.","evaluation":{"0":"short answer rhythm","1":"do/does clarity","2":"question intonation","open_response":true,"status":"pending_rubric"},"estimated_seconds":110,"difficulty":null,"target_error":null,"hint":null,"source_lesson_id":"A1-M2-T03-L02","pronunciation":{"target":"Producir respuestas cortas rápidas sin perder do/does.","models":[{"text":"Yes, I do.","stress":["yes","do"]},{"text":"No, she doesn''t.","stress":["no","doesn''t"]},{"text":"Yes, they do.","stress":["yes","do"]}],"student_feedback":"La palabra final do/doesn''t completa la respuesta; no la elimines."}}'::jsonb,'Las respuestas son breves pero completas.','No elimines do/does; marca la respuesta final.',110,1,6,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
