antiene la comunicación activa.','',45,1,2,true) on conflict(lesson_id,sort_order) do update set content_code=excluded.content_code,exercise_type=excluded.exercise_type,skill=excluded.skill,instruction=excluded.instruction,prompt=excluded.prompt,explanation=excluded.explanation,correct_answer=excluded.correct_answer,content_payload=excluded.content_payload,feedback_correct=excluded.feedback_correct,feedback_incorrect=excluded.feedback_incorrect,estimated_seconds=excluded.estimated_seconds,is_published=true returning id into v_exercise_id;
